/// <summary>
/// Per-company visibility setup for the CELT custom input fields: every field the model adds to a
/// standard form has one row here, and its Enabled flag decides whether the control shows on the
/// form (CELTFieldSetupVisibility hides disabled controls at form open). A field with no row is
/// treated as enabled, so the setup can never blank out a form by accident.
/// </summary>
public class CELTFieldSetup extends common
{
}

Method.Source:
/// <summary>
/// Whether the given custom field is enabled for the given area in the current company.
/// Area Any means "enabled anywhere" - used by forms that are not document-specific (legal
/// entity, products, tax codes, addresses). A missing row counts as enabled - the default is
/// to show everything.
/// </summary>
/// <param name = "_fieldName">the table field name, e.g. CELTAETransactionType</param>
/// <param name = "_area">Sales, Purchase, Project - or Any for the OR of all three</param>
/// <returns>true when the field should be visible in that area</returns>
public static boolean isEnabled(str _fieldName, CELTFieldArea _area = CELTFieldArea::Any)
{
    CELTFieldSetup setup;

    select firstonly EnabledSales, EnabledPurchase, EnabledProject, RecId from setup
        where setup.FieldName == _fieldName;

    if (!setup.RecId)
    {
        return true;
    }

    switch (_area)
    {
        case CELTFieldArea::Sales:
            return setup.EnabledSales == NoYes::Yes;
        case CELTFieldArea::Purchase:
            return setup.EnabledPurchase == NoYes::Yes;
        case CELTFieldArea::Project:
            return setup.EnabledProject == NoYes::Yes;
        default:
            return setup.EnabledSales == NoYes::Yes
                || setup.EnabledPurchase == NoYes::Yes
                || setup.EnabledProject == NoYes::Yes;
    }
}

/// <summary>
/// Inserts a row for every CELT custom input field that has none yet (enabled everywhere by
/// default, so existing behavior is unchanged), and refreshes the description text from the
/// labels.
/// </summary>
public static void ensureSeeded()
{
    container fields = [
        ['CELTAETransactionType',       "@CELTLabels:AETransactionType"],
        ['CELTAEFrequencyOfBilling',    "@CELTLabels:AEFrequencyOfBilling"],
        ['CELTInvoicePeriodStart',      "@CELTLabels:InvoicePeriodStart"],
        ['CELTInvoicePeriodEnd',        "@CELTLabels:InvoicePeriodEnd"],
        ['CELTAECustomsRefNumber',      "@CELTLabels:AECustomsRefNumber"],
        ['CELTFRVatDueDateCode',        "@CELTLabels:FRVatDueDateCode"],
        ['CELTAEPrincipalId',           "@CELTLabels:AEPrincipalId"],
        ['CELTAEInvoiceNote',           "@CELTLabels:AEInvoiceNote"],
        ['CELTAECreditNoteReason',      "@CELTLabels:AECreditNoteReason"],
        ['CELTAELegalRegType',          "@CELTLabels:AELegalRegType"],
        ['CELTAEAuthorityName',         "@CELTLabels:AEAuthorityName"],
        ['CELTAEPassportCountry',       "@CELTLabels:AEPassportCountry"],
        ['CELTAEBeneficiaryId',         "@CELTLabels:AEBeneficiaryId"],
        ['CELTAEServiceAccountingCode', "@CELTLabels:AEServiceAccountingCode"],
        ['CELTAERcmType',               "@CELTLabels:AERcmType"],
        ['CELTAEItemType',              "@CELTLabels:AEItemType"],
        ['CELTAETaxCategory',           "@CELTLabels:AETaxCategory"],
        ['CELTAEExemptionReasonCode',   "@CELTLabels:AEExemptionReasonCode"],
        ['CELTAEExemptionReason',       "@CELTLabels:AEExemptionReason"],
        ['CELTAEFreeZoneIndicator',     "@CELTLabels:AEFreeZoneIndicator"]];

    CELTFieldSetup setup;
    int            i;

    ttsbegin;

    for (i = 1; i <= conLen(fields); i++)
    {
        container entry       = conPeek(fields, i);
        str       fieldName   = conPeek(entry, 1);
        str       description = conPeek(entry, 2);

        select forupdate firstonly setup
            where setup.FieldName == fieldName;

        if (!setup.RecId)
        {
            setup.clear();
            setup.FieldName       = fieldName;
            setup.Description     = description;
            setup.EnabledSales    = NoYes::Yes;
            setup.EnabledPurchase = NoYes::Yes;
            setup.EnabledProject  = NoYes::Yes;
            setup.insert();
        }
        else if (setup.Description != description)
        {
            setup.Description = description;
            setup.update();
        }
    }

    ttscommit;
}
